struct status{
	int x, y;
	int dirc;
	int cost; // 记录时间
};

// 这里为了方便说明，并不是要这么写
enum class jump_to : int {
	in_place_forward_1 = 0,
	in_place_forward_2 = 1,
	in_place_forward_3 = 2,
	turn_left_forward_1 = 3,
	turn_left_forward_2 = 4,
	turn_left_forward_3 = 5,
	turn_right_forward_1 = 6,
	turn_right_forward_2 = 7,
	turn_right_forward_3 = 8
};

// 这样就可以**对每一个非障碍位置遍历这九个移动方向**，检查:
// 1. 是否途径障碍
// 2. 是否出界
bool valid_jump(status& s, jump_to jt);
status jump_to_place(status& s, jump_to jt);
int main(){
	cin >> n >> m;
	vector<vector<int>> matrix(n + 1, vector<int>(m + 1, 0)); // 注意机器人走在点上，障碍物是格子
	deque<status> cur, next;
	cur.emplace(init_x, init_y, init_direction, init_cost);
	while(!cur.empty()){
		while(!cur.empty()){
			auto front = cur.front();
			for(auto _path : jump_to){
				if(valid_jump(s, _path)){
					if(front.x == x_target && front.y == y_target){
						// 记录最小cost
					}
					auto s = jump_to_place(s, _path);
					next.push(s);
				}
			}
			cur.pop_front();
		}
		cur.swap(next);
		next.clear();
	}
}
